/**
 * 생산자 구조화 에러 해석 모듈 — project-archive 구간: studio-project-archive(+zip 리더) 진단 29코드·메시지 변형 전종 (A4 D4, R12).
 *
 * 코어 모듈(studio-producer-error-i18n.ts)의 형제 모듈이다. 계약은 코어와 동일하다:
 * 생산자는 {code, variant, params}만 방출하고, 표시는 이 모듈의 리졸버로만 해석한다.
 * 키는 기존 진단 코드(SCREAMING_SNAKE)를 kebab으로 바꾼 구간 + 문구 단위 서브코드(variant)로 구성한다.
 * 같은 진단 코드에 문구가 여러 종이면 variant로 분해했고, 동적 삽입(label·kind·collection·detail)은 params로 받는다.
 * detail params는 하위 생산자(package-archive·linked-3d pass)의 원문 패스스루다 — 그 생산자 구간 전환 전까지 문장 골격만 코드화한다.
 * ko 값은 이관 전 생산자 원문과 글자 단위 동일하고, en은 신규 번역이다.
 */

import {
  FALLBACK_CHAIN,
  getLang,
  registerI18nLocaleEntries,
  resolveTranslationForDisplay,
} from "@/shared/lib/i18n";
import type {
  StudioProjectArchiveDiagnostic,
  StudioProjectArchiveError,
} from "../studio-project-archive";

function resolveProducerError(
  key: string,
  fallback: string,
  params?: Readonly<Record<string, string>>,
): string {
  const text = resolveTranslationForDisplay(getLang(), key, FALLBACK_CHAIN, fallback);
  const values = params ?? {};
  return text.replace(/\{([A-Za-z0-9_]+)\}/gu, (placeholder, token: string) =>
    Object.hasOwn(values, token) ? String(values[token]) : placeholder,
  );
}

