function projectArchiveErrorKey(code: string, variant: string): string {
  return `studio.producerError.projectArchive.${code.toLowerCase().replaceAll("_", "-")}.${variant}`;
}

/** 표시 지점 전용 해석 (project-archive 오류·진단): 생산자가 방출한 구조화 코드를 현재 로케일 문구로 바꾼다. */
export function resolveStudioProjectArchiveError(
  error: Pick<StudioProjectArchiveError, "code" | "variant" | "params">,
): string {
  const lookup = `${error.code}:${error.variant}`;
  return resolveProducerError(
    projectArchiveErrorKey(error.code, error.variant),
    PROJECT_ARCHIVE_ERROR_KO[lookup] ?? lookup,
    error.params,
  );
}

/** 표시 지점 전용 해석 (project-archive 진단): build/import 결과 diagnostics와 Error.diagnostics 동행 항목을 해석한다. */
export function resolveStudioProjectArchiveDiagnostic(
  diagnostic: Pick<StudioProjectArchiveDiagnostic, "code" | "variant" | "params">,
): string {
  return resolveStudioProjectArchiveError(diagnostic);
}

/**
 * 표시 지점 전용 해석 (project-archive, 원인 객체 진입점): 오케스트레이션 catch가
 * 원인 객체만으로 부른다. 생산자 클래스를 런타임 import하면 studio 진입 그래프에
 * archive 생산자가 끌려오므로, 이름+코드+variant 덕 타이핑으로 판정한다.
 * 해당하지 않으면 null — 호출자는 기존 메시지 경로를 유지한다(타 생산자 오류).
 */
export function resolveStudioProjectArchiveErrorFromCause(cause: unknown): string | null {
  if (!cause || typeof cause !== "object") return null;
  const { name, code, variant, params } = cause as {
    name?: unknown; code?: unknown; variant?: unknown; params?: unknown;
  };
  if (name !== "StudioProjectArchiveError" || typeof code !== "string" || typeof variant !== "string") return null;
  if (!Object.hasOwn(PROJECT_ARCHIVE_ERROR_KO, `${code}:${variant}`)) return null;
  const safeParams =
    params && typeof params === "object" && !Array.isArray(params)
      ? (params as Readonly<Record<string, string>>)
      : undefined;
  return resolveStudioProjectArchiveError({
    code: code as StudioProjectArchiveError["code"],
    variant,
    ...(safeParams ? { params: safeParams } : {}),
  });
}

/** 표시 지점 전용 해석 (project-archive, 폴백 결합형): 구조화 오류면 해석 문구, Error면 원문 메시지, 그 외에는 호출자가 준 폴백 문구를 돌려준다. */
export function resolveStudioProjectArchiveErrorMessage(cause: unknown, fallback: string): string {
  return resolveStudioProjectArchiveErrorFromCause(cause) ?? (cause instanceof Error ? cause.message : fallback);
}
